content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-20-notif-aggregate-001

=== 用户原始指令 (query.txt) ===
帮我搞个通知卡片 主体是个图 点一下能进微信 能从日历读会议日程 红色紧急提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我搞个通知卡片 主体是个图 点一下能进微信 能从日历读会议日程 红色紧急提示",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.tencent.mm",
        "abilityName": "com.tencent.mm.ui.LauncherUI",
        "uri": "weixin://"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": {
          "type": "array",
          "description": "从日历读取到的会议日程列表，卡片仅展示第一条会议。",
          "sampleValue": [
            {
              "entityName": "calendar",
              "entityId": "event-001",
              "title": "项目周会",
              "dtStart": "09:30",
              "dtEnd": "10:00",
              "eventLocation": "会议室A"
            }
          ],
          "items": {
            "type": "object",
            "description": "会议日程项。",
            "properties": {
              "entityName": {
                "type": "string",
                "description": "日程内容类别。",
                "sampleValue": "calendar"
              },
              "entityId": {
                "type": "string",
                "description": "日程索引项唯一标识符。",
                "sampleValue": "event-001"
              },
              "title": {
                "type": "string",
                "description": "会议日程标题。",
                "sampleValue": "项目周会"
              },
              "dtStart": {
                "type": "string",
                "description": "会议开始时间，当天事件使用 HH:MM 格式。",
                "sampleValue": "09:30"
              },
              "dtEnd": {
                "type": "string",
                "description": "会议结束时间，当天事件使用 HH:MM 格式。",
                "sampleValue": "10:00"
              },
              "eventLocation": {
                "type": "string",
                "description": "会议地点。",
                "sampleValue": "会议室A"
              }
            }
          }
        }
      }
    },
    "assets": {
      "heroIcon": {
        "type": "string",
        "description": "通知卡片主体日程图标路径，来自允许素材库。",
        "sampleValue": "resources/base/media/icon_schedule.png"
      }
    },
    "status": {
      "alertText": {
        "type": "string",
        "description": "红色紧急提示短文案。",
        "sampleValue": "紧急"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_schedule.png",
      "description": "日程图标，适合用于通知卡片中表达会议日程或当前安排。",
      "bindTo": "/assets/heroIcon"
    }
  ]
}

=== 待评审 DSL (card.dsl.jsonl，共 3 行) ===
{"version":"v0.9","createSurface":{"surfaceId":"surface_card","catalogId":"ohos.a2ui.extended.catalog","width":140,"height":140}}
{"version":"v0.9","updateComponents":{"surfaceId":"surface_card","root":"root","components":[{"id":"root","component":"Column","children":["top_row","meeting_title","action_button"],"itemMargin":6,"styles":{"width":140,"height":140,"padding":12,"borderRadius":18,"clip":true,"backgroundColor":"#fff1f3f5","justifyContent":"start","alignItems":"center"}},{"id":"top_row","component":"Row","children":["hero_image","summary_col"],"itemMargin":8,"styles":{"width":116,"height":52,"justifyContent":"start","alignItems":"center"}},{"id":"hero_image","component":"Image","src":"{{ ${/assets/heroIcon} }}","styles":{"width":52,"height":52,"objectFit":"contain"}},{"id":"summary_col","component":"Column","children":["alert_badge","time_text"],"itemMargin":4,"styles":{"width":56,"height":52,"justifyContent":"center","alignItems":"start"}},{"id":"alert_badge","component":"Text","content":"{{ ${/status/alertText} }}","styles":{"width":56,"height":20,"fontSize":12,"fontWeight":700,"fontColor":"#ffffffff","backgroundColor":"#ffe84026","borderRadius":10,"textAlign":"center","maxLines":1}},{"id":"time_text","component":"Text","content":"{{ ${/data/calendar/items/0/dtStart} }}","styles":{"width":56,"height":18,"fontSize":16,"fontWeight":700,"fontColor":"#e5000000","maxLines":1}},{"id":"meeting_title","component":"Text","content":"{{ ${/data/calendar/items/0/title} }}","styles":{"width":116,"height":18,"fontSize":14,"fontWeight":600,"fontColor":"#e5000000","maxLines":1,"textAlign":"center"}},{"id":"action_button","component":"Button","label":"进微信","onClick":[{"call":"clickToDeeplink","args":{"bundleName":"com.tencent.mm","abilityName":"com.tencent.mm.ui.LauncherUI","uri":"weixin://"}}],"styles":{"width":116,"height":32,"fontSize":14,"fontWeight":500,"fontColor":"#e5000000","backgroundColor":"#19000000","borderRadius":16}}]}}
{"version":"v0.9","updateDataModel":{"surfaceId":"surface_card","path":"/","value":{"data":{"calendar":{"items":[{"entityName":"calendar","entityId":"event-001","title":"项目周会","dtStart":"09:30","dtEnd":"10:00","eventLocation":"会议室A"}]}},"assets":{"heroIcon":"resources/base/media/icon_schedule.png"},"status":{"alertText":"紧急"}}}}

=== 渲染截图 ===
⚠️ 本评分以随附的 card.dsl.png 渲染截图为唯一且最终的依据。请务必先认真看图，根据图中实际呈现的效果打分；上面的 DSL 与 system 中的布局公式仅用于协议合规性检查与改进版 DSL 的撰写，绝不能仅凭 DSL 文本/数值给分。排版与美观问题以截图为准。

输出要求：严格按 system 中规定的 JSON schema 输出单个 JSON 对象，reasons 必须基于截图描述具体视觉现象，improved_dsl 为 3 行合法 JSONL。
